function CatJumpCurve:__init()
    self.controller = nil

    self.spawnTime = 0.0

    self._colors = { Color.white, Color.white, Color.white }

    self.ts = { 0.0, 0.3, 0.75 }

    self.material = nil
end



function CatJumpCurve:__delete()

end


function CatJumpCurve:Init()
    KTool.SetActive(self.controller.gameObject, true)   
    
    -- ==============================
    -- 绑定 Update() 函数:
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.UpdateAction = function(behaviourAction)
            self:Update()
        end
    end
    -- ================== self ================:

    assert( self.mRenderer )
    self.material = self.mRenderer.sharedMaterial


    self.params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.params )

    -- 从猫头到曲线起点的偏移向量:
    self.catHeadOffset = LuaParametersReader.Read( self.params, "catHeadOffset", LuaParametersType.Vector2 ) -- (0.05, 0.15)

    -- 曲线终点垂直偏移:
    self.endPointVerticalOffset = LuaParametersReader.Read( self.params, "endPointVerticalOffset", LuaParametersType.Float ) -- 0.15


    -- 上跳用曲线参数:
    self.up_wPecent = LuaParametersReader.Read( self.params, "up_wPecent", LuaParametersType.Float ) -- 0.65
    self.up_hPecent = LuaParametersReader.Read( self.params, "up_hPecent", LuaParametersType.Float ) -- 1.2

    -- 下跳用曲线参数:
    self.down_wPecent = LuaParametersReader.Read( self.params, "down_wPecent", LuaParametersType.Float ) -- 0.65
    self.down_hPecent = LuaParametersReader.Read( self.params, "down_hPecent", LuaParametersType.Float ) -- 1.2

    -- 前跳用曲线参数:
    self.forward_wPecent = LuaParametersReader.Read( self.params, "forward_wPecent", LuaParametersType.Float ) -- 0.5
    self.forward_hPecent = LuaParametersReader.Read( self.params, "forward_hPecent", LuaParametersType.Float ) -- 0.25


    -- 跳跃曲线 颜色:
    self.color1 = LuaParametersReader.Read( self.params, "color1", LuaParametersType.Color )
    self.color2 = LuaParametersReader.Read( self.params, "color2", LuaParametersType.Color )
    self.color3 = LuaParametersReader.Read( self.params, "color3", LuaParametersType.Color )


    assert( self.splineComputer )

    self.renderer = KTool.GetOrAddComponent(self.controller.gameObject, typeof(Renderer))
    assert( self.renderer )
end




function CatJumpCurve:OnDestroy()

    self.co_1 = nil
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end




function CatJumpCurve:Update()


    if DreamSpaceStates.isShowCatJumpCurve == false then 
        self:Hide( Vector3( 10000, 0, 0 ) )
        return;
    end

    local time = Time.time % 10000.0
    self:_UpdateSpeed(time)

    for i = 1, table.count(self.ts) do
        local t = self.ts[i] - Time.deltaTime * speed
        t = (t < 0) and t + 1 or t
        self.ts[i] = t 
        -- ---
        self._colors[i] = self:_GetColor(t)
    end

    self.material:SetColor("_Color1", self._colors[1])
    self.material:SetColor("_Color2", self._colors[2])
    self.material:SetColor("_Color3", self._colors[3])

end




-- =============================================================== Self -> ================================================================== -- 



function CatJumpCurve:Hide( catHeadPos_ )
    local isSetInThisFrame = self:SetRendererEnabled( false  )

    if isSetInThisFrame == true then
        -- !!! 会引发 GC, 确保不要每帧都触发
        self.splineComputer:SetPoint(0, SplinePoint( catHeadPos_ ))
        self.splineComputer:SetPoint(1, SplinePoint( catHeadPos_ ))
        self.splineComputer:SetPoint(2, SplinePoint( catHeadPos_ ))
    end
end 



function CatJumpCurve:ShowJump( catHeadPos_, jumpPos_ )

    self:SetRendererEnabled( true )

    local forwardDir = Vector3.ProjectOnPlane( jumpPos_ - catHeadPos_, Vector3.up) -- xz平面的 运动方向
    local absHeight = Mathf.Abs( catHeadPos_.y - jumpPos_.y ) -- 绝对高度差

    local isPlat = (forwardDir.magnitude / absHeight) > 4.0 -- true 表示起点终点高度差不大, 是个平坦的前跳
    local isUpJump = jumpPos_.y > catHeadPos_.y 

    forwardDir:Normalize()

    local beginPos = catHeadPos_ + forwardDir * self.catHeadOffset.x + Vector3.up * self.catHeadOffset.y
    local endPos = jumpPos_ + Vector3.up * self.endPointVerticalOffset
    local midPos = nil


    local moveVector = endPos - beginPos


    if isPlat then
        -- [-- 平坦的前跳 --]
        local wPecent = self.forward_wPecent
        local hPecent = self.forward_hPecent

        local horizontalMoveDistance = Vector3.ProjectOnPlane( moveVector, Vector3.up).magnitude
        midPos = Vector3.Lerp( beginPos, endPos, wPecent )
        midPos.y = (isUpJump and beginPos.y or endPos.y) +  horizontalMoveDistance * hPecent

    else 
        -- [-- 上跳 or 下跳 --]
        local wPecent = isUpJump and self.up_wPecent or self.down_wPecent
        local hPecent = isUpJump and self.up_hPecent or self.down_hPecent

        midPos = Vector3.Lerp( beginPos, endPos, wPecent )
        midPos.y = (isUpJump and beginPos.y or endPos.y) +  absHeight * hPecent
            
    end 

    -- !!! 会引发 GC, 确保不要每帧都触发
    self.splineComputer:SetPoint(0, SplinePoint( beginPos ))
    self.splineComputer:SetPoint(1, SplinePoint( midPos ))
    self.splineComputer:SetPoint(2, SplinePoint( endPos ))
end







-- ret isSet [bool]
function CatJumpCurve:SetRendererEnabled( isEnable_ )
    if self.renderer.enabled ~= isEnable_ then 
        self.renderer.enabled = isEnable_
        return true
    end    
    return false
end 




-- 基于 t: [0,1] 计算曲线 pos 值
function CatJumpCurve:_CalcCurvePos( t_ )


    local splineLength = self.splineComputer:CalculateLength() -- float  曲线总长度

    local travel = self.splineComputer:Travel( 0.0, splineLength * t_, Spline.Direction.Forward) -- 内部 t 值
    local sample = self.splineComputer:Evaluate( travel ) -- SplineSample

    return sample.position

end 



function CatJumpCurve:_UpdateSpeed(time)
    local c = Mathf.Cos(time)
    speed = KTool.Remap(-1, 1, colorChangeMinSpeed, colorChangeMaxSpeed, c)
end



function CatJumpCurve:_GetColor(t)
    if t < 0.25 then
        return Color.Lerp(self.color1, self.color2, KTool.Remap(0,    0.25,  0, 1, t))
    elseif t < 0.75 then
        return Color.Lerp(self.color2, self.color3, KTool.Remap(0.25, 0.75,  0, 1, t))
    else
        return Color.Lerp(self.color3, self.color1, KTool.Remap(0.75,     1, 0, 1, t))
    end
end





return CatJumpCurve